from django.db import migrations, models

from application.images import build_thumbnail


def fill_order_and_thumbnails(apps, schema_editor):
    """Number existing photos per listing and create their thumbnails."""
    Photo = apps.get_model('application', 'Photo')
    property_ids = Photo.objects.values_list('property_id', flat=True).distinct()

    for property_id in property_ids:
        photos = Photo.objects.filter(property_id=property_id).order_by('id')

        for index, photo in enumerate(photos):
            photo.order = index

            if photo.image and not photo.thumbnail:
                thumbnail = build_thumbnail(photo.image)
                if thumbnail:
                    photo.thumbnail.save(thumbnail.name, thumbnail, save=False)

            photo.save()


